package com.example.application_service.controller;import com.example.application_service.common.ApiResponse;import com.example.application_service.dto.ApplicationDtos;import com.example.application_service.exception.*;import com.example.application_service.security.RequestIdentity;import com.example.application_service.service.ApplicationService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/employer/jobs/{jobId}/applications") public class EmployerApplicationController{private final ApplicationService applications;public EmployerApplicationController(ApplicationService a){applications=a;}@GetMapping public ApiResponse<ApplicationDtos.PageData<ApplicationDtos.View>> list(@PathVariable UUID jobId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="newest")String sort,RequestIdentity identity,HttpServletRequest request){if(!"EMPLOYER".equals(identity.role()))throw new ApiException(HttpStatus.FORBIDDEN,"ACCESS_DENIED","Employer role is required");return ApiResponse.ok("Job applications retrieved",applications.employerList(jobId,identity.userId(),String.valueOf(request.getAttribute(CorrelationIdFilter.ATTRIBUTE)),page,size,sort));}}
